def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    def parse_amount(token: str) -> int:
        if token and token.isascii() and token.isdigit():
            return int(token)
        return -1

    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    for idx, op in enumerate(ops):
        parts = op.split(" ")
        if any(not p or any(c.isspace() for c in p) for p in parts):
            rejected.append(idx)
            continue

        verb = parts[0]

        if verb == "open" and len(parts) == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if amt >= 0 and acc not in balances:
                balances[acc] = amt
                history.append(("open", acc))
            else:
                rejected.append(idx)

        elif verb == "deposit" and len(parts) == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if amt > 0 and acc in balances:
                balances[acc] += amt
                history.append(("deposit", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "withdraw" and len(parts) == 3:
            acc = parts[1]
            amt = parse_amount(parts[2])
            if (
                amt > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amt
            ):
                balances[acc] -= amt
                history.append(("withdraw", acc, amt))
            else:
                rejected.append(idx)

        elif verb == "transfer" and len(parts) == 4:
            src, dst = parts[1], parts[2]
            amt = parse_amount(parts[3])
            if (
                amt > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amt
            ):
                balances[src] -= amt
                balances[dst] += amt
                history.append(("transfer", src, dst, amt))
            else:
                rejected.append(idx)

        elif verb == "freeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(idx)

        elif verb == "unfreeze" and len(parts) == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(idx)

        elif verb == "undo" and len(parts) == 1:
            if not history:
                rejected.append(idx)
            else:
                last = history.pop()
                kind = last[0]
                if kind == "open":
                    del balances[last[1]]
                elif kind == "deposit":
                    balances[last[1]] -= last[2]
                elif kind == "withdraw":
                    balances[last[1]] += last[2]
                elif kind == "transfer":
                    balances[last[1]] += last[3]
                    balances[last[2]] -= last[3]
                elif kind == "freeze":
                    frozen.remove(last[1])
                elif kind == "unfreeze":
                    frozen.add(last[1])

        else:
            rejected.append(idx)

    return balances, rejected
